function(container, apiUrl, tables) {
  const form = container.querySelector('#reportForm');
  const reportDate = container.querySelector('#reportDate');
  const reportContent = container.querySelector('#reportContent');
  const reportContainer = container.querySelector('#reportContainer');

  function setTodayDate() {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const day = String(today.getDate()).padStart(2, '0');
    reportDate.value = year + '-' + month + '-' + day;
  }

  function showToast(message) {
    const toast = document.createElement('div');
    toast.className = 'toast';
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(() => {
      toast.style.animation = 'slideInUp 300ms ease-out reverse';
      setTimeout(() => toast.remove(), 300);
    }, 3000);
  }

  function formatDate(dateStr) {
    const date = new Date(dateStr);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return year + '年' + month + '月' + day + '日';
  }

  function formatDateTime(dateStr) {
    const date = new Date(dateStr);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return formatDate(dateStr) + ' ' + hours + ':' + minutes;
  }

  function renderReports() {
    const selectedDate = reportDate.value;
    const today = new Date();
    const todayStr = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');

    if (!tables || !tables.reports || tables.reports.length === 0) {
      reportContainer.innerHTML = '<div class="empty-state"><div class="empty-state-icon">📝</div><div class="empty-state-text">本日の日報はまだ登録されていません</div></div>';
      return;
    }

    const todayReports = tables.reports.filter(report => report.reportDate === todayStr);

    if (todayReports.length === 0) {
      reportContainer.innerHTML = '<div class="empty-state"><div class="empty-state-icon">📝</div><div class="empty-state-text">本日の日報はまだ登録されていません</div></div>';
      return;
    }

    reportContainer.innerHTML = todayReports.map((report, idx) => `
      <div class="report-card">
        <div class="report-header">
          <div class="report-date">${formatDate(report.reportDate)}</div>
          <span class="report-status ${report.status === 'submitted' ? 'status-submitted' : 'status-draft'}">${report.status === 'submitted' ? '提出済み' : '下書き'}</span>
        </div>
        <div class="report-content">${report.content}</div>
        <div class="report-meta">
          <span>作成: ${formatDateTime(report.createdAt)}</span>
          ${report.submittedAt ? '<span>提出: ' + formatDateTime(report.submittedAt) + '</span>' : ''}
        </div>
        <div class="report-actions">
          ${report.status === 'submitted' ? '<button type="button" class="btn btn-primary" style="width: auto;" data-submit-idx="' + idx + '">通知を送信</button>' : ''}
          ${report.status === 'draft' ? '<button type="button" class="btn btn-secondary" style="width: auto;" data-edit-idx="' + idx + '">編集</button>' : ''}
          ${report.status === 'draft' ? '<button type="button" class="btn-icon" data-delete-idx="' + idx + '">🗑️</button>' : ''}
        </div>
      </div>
    `).join('');
  }

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    const date = reportDate.value;
    const content = reportContent.value.trim();

    if (!date || !content) return;

    const today = new Date();
    const todayStr = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');
    if (date !== todayStr) {
      showToast('本日の日報のみ登録できます');
      return;
    }

    if (!tables) tables = {};
    if (!tables.reports) tables.reports = [];

    const now = new Date().toISOString();
    tables.reports.push({
      id: Math.random().toString(36).substr(2, 9),
      reportDate: date,
      content: content,
      status: 'draft',
      createdAt: now,
      submittedAt: null
    });

    showToast('日報を登録しました');
    reportContent.value = '';
    renderReports();
  });

  container.addEventListener('click', function(e) {
    const submitBtn = e.target.closest('[data-submit-idx]');
    if (submitBtn) {
      const idx = parseInt(submitBtn.getAttribute('data-submit-idx'));
      const today = new Date();
      const todayStr = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');
      if (tables.reports[idx].reportDate === todayStr && tables.reports[idx].status === 'submitted') {
        tables.reports[idx].submittedAt = new Date().toISOString();
        showToast('チームに通知を送信しました');
        renderReports();
      }
    }

    const editBtn = e.target.closest('[data-edit-idx]');
    if (editBtn) {
      const idx = parseInt(editBtn.getAttribute('data-edit-idx'));
      if (tables.reports[idx].status === 'draft') {
        reportDate.value = tables.reports[idx].reportDate;
        reportContent.value = tables.reports[idx].content;
        tables.reports.splice(idx, 1);
        renderReports();
        showToast('編集モードに戻りました');
      }
    }

    const deleteBtn = e.target.closest('[data-delete-idx]');
    if (deleteBtn) {
      const idx = parseInt(deleteBtn.getAttribute('data-delete-idx'));
      if (tables.reports[idx].status === 'draft') {
        tables.reports.splice(idx, 1);
        showToast('日報を削除しました');
        renderReports();
      }
    }
  });

  setTodayDate();
  renderReports();
}

function(container, apiUrl, tables) {
  const periodFilter = container.querySelector('#periodFilter');
  const submittedCount = container.querySelector('#submittedCount');
  const submissionRate = container.querySelector('#submissionRate');
  const pendingCount = container.querySelector('#pendingCount');
  const submittedList = container.querySelector('#submittedList');
  const pendingList = container.querySelector('#pendingList');
  const tableBody = container.querySelector('#tableBody');

  const teamMembers = [
    { id: 1, name: '田中太郎' },
    { id: 2, name: '鈴木花子' },
    { id: 3, name: '佐藤次郎' },
    { id: 4, name: '高橋美咲' },
    { id: 5, name: '伊藤健太' }
  ];

  function getTodayStr() {
    const today = new Date();
    return today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');
  }

  function formatDate(dateStr) {
    const date = new Date(dateStr);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return year + '年' + month + '月' + day + '日';
  }

  function formatDateTime(dateStr) {
    const date = new Date(dateStr);
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return formatDate(dateStr) + ' ' + hours + ':' + minutes;
  }

  function getMemberStatus(memberId) {
    if (!tables || !tables.reports) return { submitted: false, lastDate: null };
    const todayStr = getTodayStr();
    const report = tables.reports.find(r => r.memberId === memberId && r.reportDate === todayStr && r.status === 'submitted');
    return { submitted: !!report, lastDate: report ? report.submittedAt : null };
  }

  function updateDashboard() {
    const todayStr = getTodayStr();
    const submitted = teamMembers.filter(m => getMemberStatus(m.id).submitted);
    const pending = teamMembers.filter(m => !getMemberStatus(m.id).submitted);
    const rate = Math.round((submitted.length / teamMembers.length) * 100);

    submittedCount.textContent = submitted.length;
    pendingCount.textContent = pending.length;
    submissionRate.textContent = rate;

    if (submitted.length > 0) {
      submittedList.innerHTML = submitted.map(m => `
        <div class="member-item">
          <div class="member-name">
            <div class="member-icon">✓</div>
            <div>${m.name}</div>
          </div>
          <div class="member-detail">${formatDateTime(getMemberStatus(m.id).lastDate || new Date().toISOString())}</div>
        </div>
      `).join('');
    } else {
      submittedList.innerHTML = '<div class="empty-list">本日提出済みのメンバーはまだいません</div>';
    }

    if (pending.length > 0) {
      pendingList.innerHTML = pending.map(m => `
        <div class="member-item">
          <div class="member-name">
            <div class="member-icon">⏱</div>
            <div>${m.name}</div>
          </div>
          <div class="member-detail">未提出</div>
        </div>
      `).join('');
    } else {
      pendingList.innerHTML = '<div class="empty-list">全メンバーが提出済みです！</div>';
    }

    const rows = teamMembers.map((m, idx) => {
      const status = getMemberStatus(m.id);
      const statusClass = status.submitted ? 'status-submitted' : 'status-pending';
      const statusText = status.submitted ? '提出済み' : '未提出';
      const lastDateText = status.lastDate ? formatDateTime(status.lastDate) : '—';
      return `
        <tr>
          <td>${m.name}</td>
          <td><span class="status-badge ${statusClass}">● ${statusText}</span></td>
          <td>${lastDateText}</td>
          <td><button class="btn-icon" data-member-id="${m.id}" title="詳細表示">👁</button></td>
        </tr>
      `;
    }).join('');

    if (rows.length > 0) {
      tableBody.innerHTML = rows;
    } else {
      tableBody.innerHTML = '<tr><td colspan="4" class="no-data"><div class="no-data-icon">📊</div><div class="no-data-text">メンバー情報がありません</div></td></tr>';
    }
  }

  periodFilter.addEventListener('change', function(e) {
    updateDashboard();
  });

  container.addEventListener('click', function(e) {
    const btn = e.target.closest('[data-member-id]');
    if (btn) {
      const memberId = parseInt(btn.getAttribute('data-member-id'));
      const member = teamMembers.find(m => m.id === memberId);
      alert(member.name + 'さんの詳細情報表示機能は実装予定です');
    }
  });

  updateDashboard();
}
